n=20
g=[[0]*n for _ in range(n)]
for r in range(2,9):
  for c in range(9,16): g[r][c]=2
ones=[(2,6),(3,19),(4,5),(7,1),(8,19),(12,9),(17,13),(19,15)]
for r,c in ones:g[r][c]=1
# horizontal projections, directional blocker if marker in the ray
for r in range(2,9):
  if not any((rr,cc) in ones for rr,cc in ones if rr==r and cc<9):
    for c in range(0,9):
      if g[r][c]==0:g[r][c]=2
  if not any(rr==r and cc>15 for rr,cc in ones):
    for c in range(16,20):
      if g[r][c]==0:g[r][c]=2
# vertical projections
for c in range(9,16):
  if not any(cc==c and rr<2 for rr,cc in ones):
    for r in range(0,2):
      if g[r][c]==0:g[r][c]=2
  if not any(cc==c and rr>8 for rr,cc in ones):
    for r in range(9,20):
      if g[r][c]==0:g[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in g))
